          '**Einschätzung von PromptQuorum:** die Scorecard, die Modelleignung und die Kauf-/Überspringen-Empfehlung, angewandt auf die oben genannten, vom Anbieter angegebenen Fakten. Die VRAM-Größen stammen aus dem PromptQuorum-Spickzettel, der im Abschnitt zur Modelleignung verlinkt ist.',
