        content:
          '**Faits uniquement, d\'après la documentation de RunPod consultée le 2026-11-22 : le paiement se fait par crédit prépayé, Secure Cloud est hébergé dans des centres de données T3/T4, et Community Cloud s\'appuie sur des fournisseurs de calcul individuels.** PromptQuorum n\'a audité ni RunPod ni ses hôtes.',
