          '**如果你想按秒租用指定型号的 GPU，并愿意留意存储费用和额度余额，就选 RunPod。** 其定价页（核实于 2026-11-22）列出从 RTX 3090 到 B300 的 GPU，Community Cloud 上 RTX 4090 为 $0.34/小时。对于一次性微调或周末测试，按秒计费意味着你只为实际用到的分钟付费。\n\n**选择 RunPod 并不是因为它每一项都最便宜；而是当 GPU 种类、按秒计费和有文档的 Serverless vLLM 路径比退款政策更重要时，它才是合适的选择。** 额度不可退款，文档也没有描述 Community Cloud 的安全性，因此敏感数据应放在 Secure Cloud 上，或不要放在该平台。\n\n如果主要问题是与点对点市场比价，请在充值前先阅读 [RunPod 与 Vast.ai 价格对比](/zh/prompt-bites/runpod-vs-vastai-pricing)。',
