          '**Cold starts:** um worker é cobrado durante o cold start e durante o tempo limite de ociosidade. A RunPod documenta o FlashBoot como a retenção do estado do worker após o desligamento, para uma reativação mais rápida; a documentação não dá números de tempo e diz que ele funciona melhor em endpoints com tráfego constante.',
