          '**vLLM no Serverless:** a RunPod documenta um worker vLLM que pode ser implantado pelo RunPod Hub, descrito como substituto direto da API da OpenAI (troque a URL do endpoint e a chave de API). Os detalhes de configuração estão na [documentação do worker vLLM da RunPod](https://docs.runpod.io/serverless/vllm/overview). Para entender melhor o motor, veja [vLLM explicado](/pt/power-local-llm/vllm-explained).',
          '**Volume de rede:** mantém os pesos do modelo fora de qualquer Pod específico, para que você não precise baixá-los de novo a cada vez.',
